const line=(a,b)=>({a,b}),port=(face,a=3,b=5,more={})=>({id:face,face,a,b,height:2.4,...more}),box=(x,z,w,d,h=.6)=>({x,z,w,d,h,color:'wood'});
const root=(id,name,cells=[[0,0]])=>({id,name,use:'residential',family:'R7',color:'#9cae9c',cells,ceiling:2.7,ports:[],walls:[],doors:[],solids:[],furniture:[],labels:[],roofAreas:cells.map(([x,z])=>({x:x*8,z:z*8,w:8,d:8,height:2.7}))});
const adapter=(profiles)=>({adaptive:true,profiles});
export function redesign(bodies){
 const get=id=>bodies.find(b=>b.id===id),keep=(id,faces)=>get(id).ports=get(id).ports.filter(p=>faces.includes(p.id)),fixed=(id,face)=>Object.assign(get(id).ports.find(p=>p.id===face),{permanent:true});
 keep('D1',['W','E']);keep('D2',['W','S']);keep('D3',['E']);keep('D4',['N','W']);for(const [id,f]of[['D1','E'],['D2','W'],['D2','S'],['D4','N'],['D3','E'],['D4','W']])fixed(id,f);
 keep('U1',['W','E','S']);keep('U2',['N','W']);keep('U3',['W','E','S']);keep('U4',['N','S']);keep('N2',['N','bio']);keep('N1',['S','W','bio']);keep('N3',['S','bio']);
 for(const [id,f]of[['U1','S'],['U2','N'],['U3','S'],['U4','N'],['U4','S'],['N2','N'],['U5','E'],['N1','S'],['N3','S']])fixed(id,f);
 Object.assign(get('U5').ports.find(p=>p.id==='S'),port('S',1,7,adapter([[1,7]])));get('U5').solids=get('U5').solids.filter(s=>s.x<5);get('U5').name='居住区の共用前室';get('U5').color='#9cae9c';
 for(const id of ['R1','R4','K1']){get(id).family='R7';get(id).color='#9cae9c';}get('K1').furniture=[box(.4,.5,1.4,1.5),box(6,1,1.2,.6,.8)];
 const v1=root('V1','三連結L型住宅・共用翼',[[0,0],[0,1],[1,1]]);v1.ports=[port('N',1,7,adapter([[1,7]])),port('W',3,5,adapter([[3.25,4.75]]))];v1.walls=[line([0,2.6],[2.8,2.6]),line([2.8,0],[2.8,1]),line([2.8,2.2],[2.8,2.6]),line([8,11],[12.8,11]),line([14,11],[16,11])];v1.doors=[{id:'V1-door',a:[2.8,1],b:[2.8,2.2],open:false,label:'小居室'},{id:'V1-wing',a:[12.8,11],b:[14,11],open:false,label:'奥の居室'}];v1.furniture=[box(.5,.5,1.4,1.5),box(10,13,2,1),box(1,12,1.4,.6,.8)];v1.labels=[{name:'共用廊下',x:4,z:6},{name:'居室と談話翼',x:11,z:13}];bodies.push(v1);
 const v2=root('V2','二連結住宅・ふたつの居室',[[0,0],[1,0]]);v2.ports=[port('N',1,7,adapter([[3,5]])),port('W')];v2.walls=[line([3,0],[3,1]),line([3,2.2],[3,3]),line([0,3],[3,3]),line([11,0],[11,1]),line([11,2.2],[11,3]),line([11,3],[16,3])];v2.doors=[{id:'V2-west',a:[3,1],b:[3,2.2],open:false,label:'西居室'},{id:'V2-east',a:[11,1],b:[11,2.2],open:false,label:'東居室'}];v2.furniture=[box(.5,.5,1.4,1.6),box(13,.6,1.5,1.5),box(8,6,2,.6)];v2.labels=[{name:'一体の生活廊下',x:8,z:4.2}];bodies.push(v2);
 const v3=root('V3','単独住宅・片寄せ前廊下');v3.ports=[port('N',2,7,adapter([[3,5],[5,7]])),port('W',1,7,{...adapter([[3,5]]),cycles:['A']}),port('E',1,7,adapter([[3,5]])),port('S')];v3.walls=[line([0,2.7],[3.4,2.7]),line([3.4,0],[3.4,1]),line([3.4,2.2],[3.4,2.7])];v3.doors=[{id:'V3-door',a:[3.4,1],b:[3.4,2.2],open:false,label:'仮の居室'}];v3.furniture=[box(.5,.5,1.5,1.3),box(1,6,1.4,.6,.8)];v3.labels=[{name:'片寄せ生活廊下',x:5.5,z:4}];bodies.push(v3);
 const a3=root('A3','中央の共用玄関');a3.use='common';a3.ports=[port('N',1,7,adapter([[3,5]])),port('E'),port('S',3,5,{permanent:true})];a3.furniture=[box(1,1,1.2,1),box(6,6,1,.7)];a3.labels=[{name:'中央共用部',x:4,z:4}];bodies.push(a3);
 const q=root('Q1','二連結の予備点検廊下',[[0,0],[0,1]]);q.use='corridor';q.color='#a3a58b';q.ceiling=2.3;q.roofAreas=q.cells.map(([x,z])=>({x:0,z:z*8,w:8,d:8,height:2.3}));q.ports=[port('N',3.25,4.75,{height:2.15}),port('S',3.25,4.75,{height:2.15}),port('E',11.65,13.15,{height:2.15})];
 const points=[[4,0],[4,6],[5.4,7.4],[5.4,10],[4,11.4],[4,16]],offset=side=>points.map((p,i)=>{const normal=(a,b)=>{const dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz);return[-dz/len*side,dx/len*side];};const n1=normal(points[Math.max(0,i-1)],points[Math.max(1,i)]),n2=normal(points[Math.min(i,points.length-2)],points[Math.min(i+1,points.length-1)]),dot=n1[0]*n2[0]+n1[1]*n2[1],scale=.75/(1+dot);return[p[0]+(n1[0]+n2[0])*scale,p[1]+(n1[1]+n2[1])*scale];});
 for(const side of [-1,1]){const ps=offset(side);for(let i=0;i<ps.length-1;i++){const a=ps[i],b=ps[i+1];if(side===-1&&i===ps.length-2){q.walls.push(line(a,[b[0],11.65]),line([b[0],13.15],b));}else q.walls.push(line(a,b));}}q.walls.push(line([4.75,11.65],[8,11.65]),line([4.75,13.15],[8,13.15]));q.labels=[{name:'幅1.38m・点検通路',x:4,z:4},{name:'斜行区間',x:4.7,z:9}];bodies.push(q);
 const w=root('W1','南端の旧設備室');w.use='common';w.ports=[port('N',3.25,4.75)];w.furniture=[box(.6,.6,1.7,2,1.6),box(5,4,2,1,1)];w.labels=[{name:'旧設備室',x:4,z:4}];bodies.push(w);
 get('R2').furniture[0]={...get('R2').furniture[0],x:3.7,w:1.3};for(const id of ['U2','U4'])get(id).furniture=[box(.4,.4,1,.8,.8)];v1.furniture[0]=box(.4,1.2,1.1,1.1);v2.furniture[0]=box(.4,1.2,1.1,1.1);v3.furniture[0]=box(1,1,1.1,1.3);
 // Every ordinary door gets an explicit safe inward hinge, not an exposed sliding leaf.
 for(const b of bodies)for(const d of b.doors){d.kind='hinge';d.hinge='a';d.swing=-90;if(d.id==='R2-door'||d.id==='T2-door'||/^E[1-4]-/.test(d.id)||/^D[23]-/.test(d.id)||d.id==='V1-wing'){d.hinge='b';d.swing=90;}if(d.id==='R3-door')d.swing=90;if(d.a[0]===d.b[0]){d.hinge='b';d.swing=-90;if(d.id==='V2-east')d.swing=90;}}
}
export const Q_STORAGE={x:117.6,y:6.4,z:0};
export function redesignPlacements(phase,p){p.N1={...p.N1,angle:90};p.N3={x:8.4,y:12.8,z:33.6,angle:180};return Object.assign(p,{V1:{x:8.4,y:-12.8,z:phase==='B'?25.2:16.8},V2:{x:phase==='C'?8.4:16.8,y:phase==='B'?12.8:0,z:25.2},V3:phase==='B'?{x:0,y:-12.8,z:8.4}:{x:8.4,y:12.8,z:16.8},A3:{x:8.4,y:12.8,z:25.2},Q1:phase==='B'?{x:0,y:-12.8,z:16.8}:{...Q_STORAGE},W1:{x:0,y:-12.8,z:33.6}});}
